GOAL:
{'id': 'arch-04-api-gateway-migration', 'description': 'Migrate from NGINX to Kong API gateway: export NGINX config (routes, upstreams, SSL certs), translate to Kong declarative config, deploy Kong alongside NGINX, route shadow traffic for validation, cutover DNS to Kong. Must preserve all rate limiting, auth, and rewrite rules.', 'constraints': {'budget': {'max_tokens': None, 'max_calls': None, 'max_revisions': None}, 'time': None, 'environment': 'production', 'tools': ['kong', 'deck', 'nginx', 'kubectl', 'dns', 'terraform']}, 'risk_tolerance': 'strict', 'replan_policy': 'restart', 'approval_ttl': None, 'metadata': {}}

